cd /app; cat > /tmp/r.py <<'E'
import os,sys
R=int(sys.argv[1]); svc=sys.argv[2]; env='prod-b'; host='app-07'
def getf(p):  # p abs under /app/config
    rel=os.path.relpath(p,'/app/config')
    for r in range(R+1,420):
        q=f'/app/config-history/r{r:04d}/prev/{rel}'
        if os.path.exists(q): return open(q).read()
    return open(p).read()
vals={}
def read(path,top_svc_file=False):
    sec=None
    for ln in getf(path).splitlines() if not top_svc_file else open(path).read().splitlines():
        ln=ln.strip()
        if not ln or ln.startswith('#'): continue
        if ln.startswith('['): sec=ln[1:-1]; continue
        k,v=[x.strip() for x in ln.split('=',1)]
        if k=='include':
            if sec is None or top_svc_file and False:
                p=v.replace('${env}',env).replace('${host}',host)
                read(os.path.normpath(os.path.join(os.path.dirname(path),p)))
            continue
        if top_svc_file or sec is None or sec==svc:
            vals[k]=v; print(path,sec,k,v)
read(f'/app/services/{svc}/service.conf',True)
print({k:vals[k] for k in vals if k in('port_base','port_offset','admin_port','enabled')})
E
python3 /tmp/r.py 417 tagging | grep -E "port|enabled"

